import boto3
import json

s3 = boto3.client("s3", region_name="us-east-1")
bucket = "my-ml-test-bucket"  # replace with your test bucket

policy = {
    "Version": "2012-10-17",
    "Statement": [{
        "Sid": "DenyUnencryptedUploads",
        "Effect": "Deny",
        "Principal": "*",
        "Action": "s3:PutObject",
        "Resource": "arn:aws:s3:::" + bucket + "/*",
        "Condition": {
            "StringNotEquals": {"s3:x-amz-server-side-encryption": "aws:kms"}
        },
    }],
}
s3.put_bucket_policy(Bucket=bucket, Policy=json.dumps(policy))
print("Policy attached — test an unencrypted upload, then remove the policy.")
